local JesterPropsMaker = {}
local PRODUCTS = {
    juggling_balls = { name = "Žonglirske žoge", leatherCost = 2, sandCost = 1, time = 1, cost = 12, comedyValue = 30, happiness = 2, description = "Žonglirske žoge za dvorno zabavo." },
    fools_scepter = { name = "Norčeva žezla", woodCost = 2, paintCost = 1, bellCost = 1, time = 2, cost = 28, comedyValue = 45, prestige = 1, happiness = 3, description = "Norčeva žezla z zvončki." },
    jester_cap = { name = "Norčeva kapa", linenCost = 2, bellCost = 2, paintCost = 1, time = 3, cost = 55, comedyValue = 55, prestige = 2, happiness = 4, description = "Norčeva kapa z zvončki." },
    silver_bell_prop = { name = "Srebrno zvončni rekvizit", woodCost = 1, silverCost = 1, bellCost = 2, paintCost = 1, time = 5, cost = 130, comedyValue = 70, prestige = 6, happiness = 5, description = "Rekvizit s srebrnimi zvončki za plemiče." },
    gold_trim_costume = { name = "Zlatorobni kostum", silkCost = 2, goldCost = 1, silverCost = 1, bellCost = 2, paintCost = 1, time = 8, cost = 320, comedyValue = 85, prestige = 12, happiness = 7, description = "Zlatorobni kostum za visoke plemiče." },
    royal_grand_jester_kit = { name = "Kraljevski veliki norčev komplet", silkCost = 3, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, bellCost = 3, paintCost = 2, time = 13, cost = 1200, comedyValue = 100, prestige = 35, happiness = 14, description = "Veliki kraljevski norčev komplet z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Rekvizitna delavnica", cost = { gold = 240, wood = 120, stone = 150 }, upkeep = 5, qualityBonus = 5 },
    prop_room = { name = "Rekvizitnica", cost = { gold = 800, wood = 220, stone = 300, leather = 8 }, upkeep = 20, qualityBonus = 18 },
    costume_room = { name = "Kostumnica", cost = { gold = 2000, wood = 300, stone = 500, silver = 25, silk = 8 }, upkeep = 50, qualityBonus = 30 },
    royal_props_atelier = { name = "Kraljevski atelje rekvizitov", cost = { gold = 8200, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 165, qualityBonus = 55, prestigeBonus = 40 },
}
JesterPropsMaker.leatherStock = 14; JesterPropsMaker.sandStock = 14; JesterPropsMaker.woodStock = 16; JesterPropsMaker.paintStock = 12; JesterPropsMaker.bellStock = 14; JesterPropsMaker.linenStock = 10; JesterPropsMaker.silkStock = 8; JesterPropsMaker.silverStock = 8; JesterPropsMaker.goldStock = 6; JesterPropsMaker.jewelStock = 6; JesterPropsMaker.pearlStock = 4
JesterPropsMaker.productStock = {}; JesterPropsMaker.buildings = {}; JesterPropsMaker.maker = nil; JesterPropsMaker.activeMaking = {}; JesterPropsMaker.totalProducts = 0; JesterPropsMaker.dayTimer = 0
function JesterPropsMaker.init() JesterPropsMaker.leatherStock=14; JesterPropsMaker.sandStock=14; JesterPropsMaker.woodStock=16; JesterPropsMaker.paintStock=12; JesterPropsMaker.bellStock=14; JesterPropsMaker.linenStock=10; JesterPropsMaker.silkStock=8; JesterPropsMaker.silverStock=8; JesterPropsMaker.goldStock=6; JesterPropsMaker.jewelStock=6; JesterPropsMaker.pearlStock=4; JesterPropsMaker.productStock={}; JesterPropsMaker.buildings={}; JesterPropsMaker.maker=nil; JesterPropsMaker.activeMaking={}; JesterPropsMaker.totalProducts=0; JesterPropsMaker.dayTimer=0; print("[JesterPropsMaker] Royal Jester Props Maker System initialized (6 products, 4 buildings)") end
function JesterPropsMaker.hireMaker(n,s) s=s or math.random(45,85); local c=460+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; JesterPropsMaker.maker={name=n or ("Rekvizitar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rekvizitar najet: %s (spretnost: %d)",JesterPropsMaker.maker.name,s),"success") end; return true end
function JesterPropsMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function JesterPropsMaker.build(id) local ok,e=JesterPropsMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(JesterPropsMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function JesterPropsMaker.getQualityBonus() local b=0; for _,bd in ipairs(JesterPropsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function JesterPropsMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.leatherCost and JesterPropsMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.sandCost and JesterPropsMaker.sandStock<(d.sandCost or 0) then return false,"Premalo peska" end; if d.woodCost and JesterPropsMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.paintCost and JesterPropsMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.bellCost and JesterPropsMaker.bellStock<(d.bellCost or 0) then return false,"Premalo zvončkov" end; if d.linenCost and JesterPropsMaker.linenStock<(d.linenCost or 0) then return false,"Premalo lana" end; if d.silkCost and JesterPropsMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.silverCost and JesterPropsMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and JesterPropsMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and JesterPropsMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and JesterPropsMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #JesterPropsMaker.buildings==0 then return false,"Potrebna delavnica" end; if not JesterPropsMaker.maker then return false,"Potreben rekvizitar" end; return true end
function JesterPropsMaker.make(pt,qty) qty=qty or 1; local ok,e=JesterPropsMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.leatherCost then JesterPropsMaker.leatherStock=JesterPropsMaker.leatherStock-d.leatherCost*qty end; if d.sandCost then JesterPropsMaker.sandStock=JesterPropsMaker.sandStock-d.sandCost*qty end; if d.woodCost then JesterPropsMaker.woodStock=JesterPropsMaker.woodStock-d.woodCost*qty end; if d.paintCost then JesterPropsMaker.paintStock=JesterPropsMaker.paintStock-d.paintCost*qty end; if d.bellCost then JesterPropsMaker.bellStock=JesterPropsMaker.bellStock-d.bellCost*qty end; if d.linenCost then JesterPropsMaker.linenStock=JesterPropsMaker.linenStock-d.linenCost*qty end; if d.silkCost then JesterPropsMaker.silkStock=JesterPropsMaker.silkStock-d.silkCost*qty end; if d.silverCost then JesterPropsMaker.silverStock=JesterPropsMaker.silverStock-d.silverCost*qty end; if d.goldCost then JesterPropsMaker.goldStock=JesterPropsMaker.goldStock-d.goldCost*qty end; if d.jewelCost then JesterPropsMaker.jewelStock=JesterPropsMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then JesterPropsMaker.pearlStock=JesterPropsMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if JesterPropsMaker.maker then t=math.max(1,t-math.floor(JesterPropsMaker.maker.skill/12)) end; table.insert(JesterPropsMaker.activeMaking,{id="jesterprop_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,comedyValue=d.comedyValue or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function JesterPropsMaker.completeMaking(m) local q=1.0+(JesterPropsMaker.getQualityBonus()/100); if JesterPropsMaker.maker then q=q+(JesterPropsMaker.maker.skill/180) end; q=math.min(2.0,q); JesterPropsMaker.productStock[m.productType]=(JesterPropsMaker.productStock[m.productType] or 0)+m.quantity; JesterPropsMaker.totalProducts=JesterPropsMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if JesterPropsMaker.maker then JesterPropsMaker.maker.itemsMade=JesterPropsMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then JesterPropsMaker.maker.skill=math.min(100,JesterPropsMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rekvizit izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"jesterprop.completed",{productName=m.productName,comedyValue=m.comedyValue,prestige=m.prestige,happiness=m.happiness}) end end
function JesterPropsMaker.update(dt) if not _G.state then return end; JesterPropsMaker.dayTimer=JesterPropsMaker.dayTimer+dt; if JesterPropsMaker.dayTimer>=30 then JesterPropsMaker.dayTimer=0; for i=#JesterPropsMaker.activeMaking,1,-1 do local m=JesterPropsMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then JesterPropsMaker.completeMaking(m); table.remove(JesterPropsMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(JesterPropsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if JesterPropsMaker.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function JesterPropsMaker.getStats() return {leatherStock=JesterPropsMaker.leatherStock,sandStock=JesterPropsMaker.sandStock,woodStock=JesterPropsMaker.woodStock,paintStock=JesterPropsMaker.paintStock,bellStock=JesterPropsMaker.bellStock,linenStock=JesterPropsMaker.linenStock,silkStock=JesterPropsMaker.silkStock,silverStock=JesterPropsMaker.silverStock,goldStock=JesterPropsMaker.goldStock,jewelStock=JesterPropsMaker.jewelStock,pearlStock=JesterPropsMaker.pearlStock,productStock=JesterPropsMaker.productStock,numBuildings=#JesterPropsMaker.buildings,hasMaker=JesterPropsMaker.maker~=nil,makerName=JesterPropsMaker.maker and JesterPropsMaker.maker.name or "—",makerSkill=JesterPropsMaker.maker and JesterPropsMaker.maker.skill or 0,activeMaking=#JesterPropsMaker.activeMaking,totalProducts=JesterPropsMaker.totalProducts} end
return JesterPropsMaker
